// Test Case Tracker front-end. No build step or server required - just open index.html.
//
// Data model:
//  - SEED_TESTCASES / EXECUTION_RESULTS are loaded from data/*.js (plain globals, not fetched,
//    so this page works when opened directly as a file:// URL without hitting CORS issues).
//  - The working list of test cases lives in localStorage so manual edits persist across reloads.
//  - EXECUTION_RESULTS is regenerated by TestCaseTracker.java after every automated run and is
//    always treated as the source of truth for any test case whose "automated" flag is set.
const STORAGE_KEY = "ttt_testcases_v1";

function loadTestCases() {
  const raw = localStorage.getItem(STORAGE_KEY);
  if (raw) {
    try { return JSON.parse(raw); } catch (e) { /* fall through to seed */ }
  }
  const seeded = SEED_TESTCASES.map(tc => ({ ...tc }));
  saveTestCases(seeded);
  return seeded;
}

function saveTestCases(list) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
}

let testCases = loadTestCases();

// Mutable copy of the script-tag-loaded EXECUTION_RESULTS, refreshed from the server after a
// "Run" so results show up without needing a page reload (EXECUTION_RESULTS itself is `const`).
let liveExecutionResults = Object.assign({}, EXECUTION_RESULTS);

/** Merges automation execution results onto an automated test case. Manual cases use their own fields. */
function getEffectiveState(tc) {
  if (tc.automated && tc.automationKey && liveExecutionResults[tc.automationKey]) {
    const r = liveExecutionResults[tc.automationKey];
    return { status: r.status || "Not Run", lastRun: r.lastRun || null, history: r.history || [] };
  }
  if (tc.automated) {
    return { status: "Not Run", lastRun: null, history: [] };
  }
  return { status: tc.manualStatus || "Not Run", lastRun: tc.manualLastRun || null, history: tc.manualHistory || [] };
}


function statusBadgeClass(status) {
  switch (status) {
    case "Pass": return "badge-pass";
    case "Fail": return "badge-fail";
    case "Blocked": return "badge-blocked";
    default: return "badge-notrun";
  }
}

function escapeHtml(str) {
  return String(str ?? "").replace(/[&<>"']/g, c => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[c]));
}

function formatDate(iso) {
  if (!iso) return "-";
  const d = new Date(iso);
  return isNaN(d.getTime()) ? iso : d.toLocaleString();
}

function render() {
  renderSummary();
  renderTable();
}

function renderSummary() {
  const states = testCases.map(getEffectiveState);
  const total = states.length;
  const counts = { Pass: 0, Fail: 0, Blocked: 0, "Not Run": 0 };
  states.forEach(s => { counts[s.status] = (counts[s.status] || 0) + 1; });
  const automatedCount = testCases.filter(tc => tc.automated).length;
  const pct = total ? Math.round((automatedCount / total) * 100) : 0;

  const cards = [
    ["Total", total],
    ["Pass", counts.Pass],
    ["Fail", counts.Fail],
    ["Blocked", counts.Blocked],
    ["Not Run", counts["Not Run"]],
    ["Automated", `${automatedCount} (${pct}%)`]
  ];
  document.getElementById("summaryCards").innerHTML = cards.map(([label, value]) =>
    `<div class="card"><div class="value">${value}</div><div class="label">${label}</div></div>`
  ).join("");
}

function currentFilters() {
  return {
    search: document.getElementById("searchInput").value.trim().toLowerCase(),
    status: document.getElementById("statusFilter").value,
    priority: document.getElementById("priorityFilter").value,
    automated: document.getElementById("automatedFilter").value
  };
}

/** Same predicate renderTable uses, pulled out so "Run All" can target exactly what's visible. */
function getFilteredTestCases() {
  const f = currentFilters();
  return testCases.filter(tc => {
    const state = getEffectiveState(tc);
    if (f.search && !(tc.id.toLowerCase().includes(f.search) || tc.title.toLowerCase().includes(f.search))) return false;
    if (f.status && state.status !== f.status) return false;
    if (f.priority && tc.priority !== f.priority) return false;
    if (f.automated && String(!!tc.automated) !== f.automated) return false;
    return true;
  });
}

// ---- Page folders: group test cases by their linked Page Object file ----
// Known Page Object files on disk (from /api/pages, refreshed in refreshFileDatalists) so a
// freshly created page shows up as an empty folder even before any test case links to it.
let knownPages = [];
// Group keys the user has collapsed - persists across re-renders in this session (default: open).
const collapsedGroups = new Set();

function humanizeClassName(name) {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1 $2");
}

function pageFolderLabel(pageClassFile) {
  const className = pageClassFile.split("/").pop().replace(/\.java$/, "");
  return humanizeClassName(className);
}

/** Buckets the given test cases by pageClassFile, plus any known Page Object with no test cases yet. */
function buildPageGroups(filteredTcs) {
  const groups = new Map(); // file path ("" for ungrouped) -> { label, file, testCases }
  filteredTcs.forEach(tc => {
    const file = tc.pageClassFile || "";
    if (!groups.has(file)) {
      groups.set(file, { label: file ? pageFolderLabel(file) : "Ungrouped", file, testCases: [] });
    }
    groups.get(file).testCases.push(tc);
  });
  knownPages.forEach(p => {
    if (!groups.has(p.relativePath)) {
      groups.set(p.relativePath, { label: humanizeClassName(p.className), file: p.relativePath, testCases: [] });
    }
  });
  const named = [...groups.values()].filter(g => g.file).sort((a, b) => a.label.localeCompare(b.label));
  const ungrouped = groups.has("") ? [groups.get("")] : [];
  return [...named, ...ungrouped];
}

function buildRowHtml(tc) {
  const state = getEffectiveState(tc);
  return `
        <tr>
        <td>${escapeHtml(tc.id)}</td>
        <td>${escapeHtml(tc.title)}</td>
        <td>${escapeHtml(tc.priority)}</td>
        <td>${escapeHtml(tc.requirement || "-")}</td>
        <td>${tc.automated ? '<span class="tag-automated">Automated</span>' : '<span class="tag-manual">Manual</span>'}</td>
        <td><span class="badge ${statusBadgeClass(state.status)}">${escapeHtml(state.status)}</span></td>
        <td>${formatDate(state.lastRun)}</td>
        <td class="row-actions">
          <button class="btn" data-action="view-history" data-id="${escapeHtml(tc.id)}">History</button>
          ${tc.automated ? `<button class="btn" data-action="run" data-id="${escapeHtml(tc.id)}">Run</button>` : `<button class="btn" data-action="mark-result" data-id="${escapeHtml(tc.id)}">Mark Result</button>`}
          <button class="btn" data-action="code" data-id="${escapeHtml(tc.id)}">Code</button>
          <button class="btn" data-action="edit" data-id="${escapeHtml(tc.id)}">Edit</button>
          <button class="btn btn-danger" data-action="delete" data-id="${escapeHtml(tc.id)}">Delete</button>
        </td>
        </tr>`;
}

function renderTable() {
  const container = document.getElementById("pageGroupsContainer");
  const groups = buildPageGroups(getFilteredTestCases());

  if (groups.length === 0) {
    container.innerHTML = `<p class="empty-state">No test cases match the current filters.</p>`;
    return;
  }

  container.innerHTML = groups.map(g => {
    const isOpen = !collapsedGroups.has(g.file);
    const passCount = g.testCases.filter(tc => getEffectiveState(tc).status === "Pass").length;
    const countBadge = g.testCases.length
      ? `<span class="page-group-count">${passCount}/${g.testCases.length} passed</span>`
      : `<span class="page-group-count page-group-empty">No test cases yet</span>`;
    const table = g.testCases.length ? `
        <table class="tc-table">
          <thead>
            <tr><th>ID</th><th>Title</th><th>Priority</th><th>Requirement</th><th>Type</th><th>Status</th><th>Last Run</th><th>Actions</th></tr>
          </thead>
          <tbody>${g.testCases.map(buildRowHtml).join("")}</tbody>
        </table>` : "";
    return `
      <details class="page-group" data-group="${escapeHtml(g.file)}"${isOpen ? " open" : ""}>
        <summary>
          <span class="page-group-icon">${g.testCases.length ? "\uD83D\uDCC2" : "\uD83D\uDCC1"}</span>
          <span class="page-group-name">${escapeHtml(g.label)}</span>
          ${countBadge}
          <button type="button" class="btn page-group-add" data-action="add-to-group" data-file="${escapeHtml(g.file)}">+ Add test case</button>
        </summary>
        ${table}
      </details>`;
  }).join("");
}


// ---- Add / Edit modal ----
const editModal = document.getElementById("editModal");
const tcForm = document.getElementById("tcForm");

function openEditModal(tc) {
  document.getElementById("modalTitle").textContent = tc ? `Edit ${tc.id}` : "Add Test Case";
  document.getElementById("f-originalId").value = tc ? tc.id : "";
  document.getElementById("f-id").value = tc ? tc.id : "";
  document.getElementById("f-title").value = tc ? tc.title : "";
  document.getElementById("f-description").value = tc ? tc.description || "" : "";
  document.getElementById("f-steps").value = tc ? tc.steps || "" : "";
  document.getElementById("f-expectedResult").value = tc ? tc.expectedResult || "" : "";
  document.getElementById("f-priority").value = tc ? tc.priority : "Medium";
  document.getElementById("f-requirement").value = tc ? tc.requirement || "" : "";
  document.getElementById("f-groups").value = tc ? tc.groups || "" : "";
  document.getElementById("f-automated").checked = tc ? !!tc.automated : false;
  document.getElementById("f-automationKey").value = tc ? tc.automationKey || "" : "";
  document.getElementById("f-pageClassFile").value = tc ? tc.pageClassFile || "" : "";
  document.getElementById("f-testClassFile").value = tc ? tc.testClassFile || "" : "";
  editModal.classList.add("open");
}

function closeEditModal() { editModal.classList.remove("open"); }

document.getElementById("addBtn").addEventListener("click", () => openEditModal(null));
document.getElementById("cancelBtn").addEventListener("click", closeEditModal);

tcForm.addEventListener("submit", e => {
  e.preventDefault();
  const originalId = document.getElementById("f-originalId").value;
  const id = document.getElementById("f-id").value.trim();
  if (!id) return;

  const existingIdx = testCases.findIndex(t => t.id === (originalId || id));
  const duplicate = testCases.some(t => t.id === id && t.id !== originalId);
  if (duplicate) { alert(`Test case ID "${id}" already exists.`); return; }

  const updated = {
    id,
    title: document.getElementById("f-title").value.trim(),
    description: document.getElementById("f-description").value.trim(),
    steps: document.getElementById("f-steps").value,
    expectedResult: document.getElementById("f-expectedResult").value.trim(),
    priority: document.getElementById("f-priority").value,
    requirement: document.getElementById("f-requirement").value.trim(),
    groups: document.getElementById("f-groups").value.trim(),
    automated: document.getElementById("f-automated").checked,
    automationKey: document.getElementById("f-automationKey").value.trim(),
    pageClassFile: document.getElementById("f-pageClassFile").value.trim(),
    testClassFile: document.getElementById("f-testClassFile").value.trim(),
    manualStatus: existingIdx >= 0 ? testCases[existingIdx].manualStatus || "Not Run" : "Not Run",
    manualLastRun: existingIdx >= 0 ? testCases[existingIdx].manualLastRun || null : null,
    manualHistory: existingIdx >= 0 ? testCases[existingIdx].manualHistory || [] : []
  };

  if (existingIdx >= 0) testCases[existingIdx] = updated;
  else testCases.push(updated);

  saveTestCases(testCases);
  closeEditModal();
  render();
});

// ---- Mark result modal (manual test cases) ----
const resultModal = document.getElementById("resultModal");
document.getElementById("resultForm").addEventListener("submit", e => {
  e.preventDefault();
  const id = document.getElementById("r-id").value;
  const status = document.getElementById("r-status").value;
  const note = document.getElementById("r-note").value.trim();
  const tc = testCases.find(t => t.id === id);
  if (!tc) return;
  const now = new Date().toISOString();
  tc.manualStatus = status;
  tc.manualLastRun = now;
  tc.manualHistory = tc.manualHistory || [];
  tc.manualHistory.unshift({ date: now, status, note });
  saveTestCases(testCases);
  resultModal.classList.remove("open");
  render();
});
document.getElementById("resultCancelBtn").addEventListener("click", () => resultModal.classList.remove("open"));

// ---- History modal ----
const historyModal = document.getElementById("historyModal");
document.getElementById("historyCloseBtn").addEventListener("click", () => historyModal.classList.remove("open"));

function openHistoryModal(tc) {
  const state = getEffectiveState(tc);
  const rows = (state.history || []).map(h =>
    `<tr><td>${formatDate(h.date || h.lastRun)}</td><td>${escapeHtml(h.status)}</td><td>${escapeHtml(h.note || h.errorMessage || "")}</td></tr>`
  ).join("");
  document.getElementById("historyContent").innerHTML = rows
    ? `<table><thead><tr><th>Date</th><th>Status</th><th>Note</th></tr></thead><tbody>${rows}</tbody></table>`
    : "<p>No execution history yet.</p>";
  historyModal.classList.add("open");
}

// ---- Table row actions (event delegation) ----
document.getElementById("pageGroupsContainer").addEventListener("click", e => {
  const addBtn = e.target.closest("button[data-action='add-to-group']");
  if (addBtn) {
    // Inside a <summary>, so stop it from also toggling the details element open/closed.
    e.preventDefault();
    e.stopPropagation();
    openEditModal(null);
    document.getElementById("f-pageClassFile").value = addBtn.dataset.file || "";
    return;
  }

  const btn = e.target.closest("button[data-action]");
  if (!btn) return;
  const id = btn.dataset.id;
  const tc = testCases.find(t => t.id === id);
  if (!tc) return;

  switch (btn.dataset.action) {
    case "edit":
      openEditModal(tc);
      break;
    case "code":
      openCodeModal(tc);
      break;
    case "run":
      openRunModal(tc);
      break;
    case "delete":
      if (confirm(`Delete test case ${id}?`)) {
        testCases = testCases.filter(t => t.id !== id);
        saveTestCases(testCases);
        render();
      }
      break;
    case "mark-result":
      document.getElementById("r-id").value = id;
      document.getElementById("r-status").value = tc.manualStatus || "Not Run";
      document.getElementById("r-note").value = "";
      resultModal.classList.add("open");
      break;
    case "view-history":
      openHistoryModal(tc);
      break;
  }
});

// 'toggle' doesn't bubble, so this only catches it via the capture phase (3rd arg = true).
document.getElementById("pageGroupsContainer").addEventListener("toggle", e => {
  const details = e.target;
  if (!details.classList || !details.classList.contains("page-group")) return;
  const key = details.dataset.group;
  if (details.open) collapsedGroups.delete(key);
  else collapsedGroups.add(key);
}, true);

document.getElementById("expandAllBtn").addEventListener("click", () => {
  collapsedGroups.clear();
  renderTable();
});
document.getElementById("collapseAllBtn").addEventListener("click", () => {
  document.querySelectorAll("#pageGroupsContainer details.page-group").forEach(d => collapsedGroups.add(d.dataset.group));
  renderTable();
});

// ---- Toolbar: filters, export/import/reset ----
["searchInput", "statusFilter", "priorityFilter", "automatedFilter"].forEach(id =>
  document.getElementById(id).addEventListener("input", renderTable)
);

document.getElementById("exportBtn").addEventListener("click", () => {
  const blob = new Blob([JSON.stringify(testCases, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `testcases-export-${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
});

document.getElementById("importFile").addEventListener("change", e => {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const imported = JSON.parse(reader.result);
      if (!Array.isArray(imported)) throw new Error("Expected a JSON array of test cases");
      testCases = imported;
      saveTestCases(testCases);
      render();
    } catch (err) {
      alert("Failed to import: " + err.message);
    } finally {
      e.target.value = "";
    }
  };
  reader.readAsText(file);
});

document.getElementById("resetBtn").addEventListener("click", () => {
  if (!confirm("Reset all test cases to the seed data? Manual edits will be lost.")) return;
  localStorage.removeItem(STORAGE_KEY);
  testCases = loadTestCases();
  render();
});

// ---- Code modal: view/edit the real Page Object + Test class source behind a test case ----
// Needs tools/testcase-tracker/server.js running (fetch calls fail silently to a banner
// when the page is opened directly as a file:// URL, since there's no backend to talk to).
const codeModal = document.getElementById("codeModal");
const codeOfflineBanner = document.getElementById("codeOfflineBanner");
let activeCodeTc = null;

/** Falls back to the FQCN in "automationKey" (Class#method) to guess the test class's source path. */
function deriveTestFileFromAutomationKey(automationKey) {
  if (!automationKey || !automationKey.includes("#")) return "";
  const fqcn = automationKey.split("#")[0];
  return `src/test/java/${fqcn.replace(/\./g, "/")}.java`;
}

async function apiGet(path) {
  const res = await fetch(path);
  if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error || `Request failed (${res.status})`);
  return res.json();
}

async function apiPost(path, body) {
  const res = await fetch(path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body)
  });
  if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error || `Request failed (${res.status})`);
  return res.json();
}

function fillDatalist(datalistId, entries) {
  const el = document.getElementById(datalistId);
  if (!el) return;
  el.innerHTML = entries.map(e => `<option value="${escapeHtml(e.relativePath)}">${escapeHtml(e.fqcn)}</option>`).join("");
}

async function refreshFileDatalists() {
  try {
    const [pages, tests] = await Promise.all([apiGet("/api/pages"), apiGet("/api/tests")]);
    fillDatalist("pageFilesList", pages);
    fillDatalist("testFilesList", tests);
    knownPages = pages;
    codeOfflineBanner.hidden = true;
    renderTable(); // so freshly-created/discovered pages show up as folders right away
  } catch (e) {
    codeOfflineBanner.hidden = false;
  }
}

function switchCodeTab(paneId) {
  document.querySelectorAll(".code-tab").forEach(b => b.classList.toggle("active", b.dataset.pane === paneId));
  document.querySelectorAll(".code-pane").forEach(p => p.hidden = p.id !== paneId);
}

document.querySelectorAll(".code-tab").forEach(btn =>
  btn.addEventListener("click", () => switchCodeTab(btn.dataset.pane))
);

async function loadCodeFile(fileInputId, editorId, statusId) {
  const file = document.getElementById(fileInputId).value.trim();
  const status = document.getElementById(statusId);
  const editor = document.getElementById(editorId);
  if (!file) { status.textContent = "Enter a file path first."; return; }
  status.textContent = "Loading...";
  try {
    const data = await apiGet(`/api/source?file=${encodeURIComponent(file)}`);
    editor.value = data.content;
    status.textContent = `Loaded ${file}`;
    codeOfflineBanner.hidden = true;
  } catch (e) {
    editor.value = "";
    status.textContent = "";
    codeOfflineBanner.hidden = false;
  }
}

async function saveCodeFile(fileInputId, editorId, statusId) {
  const file = document.getElementById(fileInputId).value.trim();
  const status = document.getElementById(statusId);
  if (!file) { status.textContent = "Enter a file path first."; return; }
  status.textContent = "Saving...";
  try {
    await apiPost("/api/source", { file, content: document.getElementById(editorId).value });
    status.textContent = `Saved ${file}`;
    codeOfflineBanner.hidden = true;
  } catch (e) {
    status.textContent = "";
    codeOfflineBanner.hidden = false;
    alert("Failed to save: " + e.message);
  }
}

async function createCodeFile(kind) {
  const nameInputId = kind === "page" ? "newPageClassName" : "newTestClassName";
  const fileInputId = kind === "page" ? "codePageFile" : "codeTestFile";
  const editorId = kind === "page" ? "codePageEditor" : "codeTestEditor";
  const statusId = kind === "page" ? "codePageStatus" : "codeTestStatus";
  const className = document.getElementById(nameInputId).value.trim();
  if (!className) { alert("Enter a class name first, e.g. CheckoutPage"); return; }
  try {
    const data = await apiPost(`/api/${kind === "page" ? "pages" : "tests"}/new`, { className });
    document.getElementById(fileInputId).value = data.file;
    document.getElementById(editorId).value = data.content;
    document.getElementById(statusId).textContent = `Created ${data.file}`;
    document.getElementById(nameInputId).value = "";
    await refreshFileDatalists();
  } catch (e) {
    alert("Failed to create: " + e.message);
  }
}

function openCodeModal(tc) {
  activeCodeTc = tc;
  document.getElementById("codeModalTitle").textContent = `Code - ${tc.id}: ${tc.title}`;
  document.getElementById("codePageFile").value = tc.pageClassFile || "";
  document.getElementById("codeTestFile").value = tc.testClassFile || deriveTestFileFromAutomationKey(tc.automationKey);
  document.getElementById("codePageEditor").value = "";
  document.getElementById("codeTestEditor").value = "";
  document.getElementById("codePageStatus").textContent = "";
  document.getElementById("codeTestStatus").textContent = "";
  switchCodeTab("pageTab");
  refreshFileDatalists();
  if (document.getElementById("codePageFile").value) loadCodeFile("codePageFile", "codePageEditor", "codePageStatus");
  if (document.getElementById("codeTestFile").value) loadCodeFile("codeTestFile", "codeTestEditor", "codeTestStatus");
  codeModal.classList.add("open");
}

document.getElementById("codePageLoadBtn").addEventListener("click", () => loadCodeFile("codePageFile", "codePageEditor", "codePageStatus"));
document.getElementById("codeTestLoadBtn").addEventListener("click", () => loadCodeFile("codeTestFile", "codeTestEditor", "codeTestStatus"));
document.getElementById("codePageSaveBtn").addEventListener("click", () => saveCodeFile("codePageFile", "codePageEditor", "codePageStatus"));
document.getElementById("codeTestSaveBtn").addEventListener("click", () => saveCodeFile("codeTestFile", "codeTestEditor", "codeTestStatus"));
document.getElementById("codePageNewBtn").addEventListener("click", () => createCodeFile("page"));
document.getElementById("codeTestNewBtn").addEventListener("click", () => createCodeFile("test"));
document.getElementById("codeCloseBtn").addEventListener("click", () => {
  // Persist whatever file paths were set/loaded back onto the test case record.
  if (activeCodeTc) {
    activeCodeTc.pageClassFile = document.getElementById("codePageFile").value.trim();
    activeCodeTc.testClassFile = document.getElementById("codeTestFile").value.trim();
    saveTestCases(testCases);
  }
  codeModal.classList.remove("open");
});

// ---- Run modal: executes the linked automation key(s) via Maven, headed by default ----
const runModal = document.getElementById("runModal");
const runOfflineBanner = document.getElementById("runOfflineBanner");
let activeRunTc = null; // set in single-test mode, null in "Run All" mode
let activeRunKeys = []; // automationKeys targeted by the current run

async function refreshExecutionResults() {
  try {
    liveExecutionResults = await apiGet("/api/execution-data");
  } catch (e) { /* offline - keep whatever execution-data.js shipped with the page */ }
}

function openRunModal(tc) {
  activeRunTc = tc;
  activeRunKeys = tc.automationKey ? [tc.automationKey] : [];
  document.getElementById("runModalTitle").textContent = `Run - ${tc.id}: ${tc.title}`;
  document.getElementById("runOutput").textContent = "";
  document.getElementById("runStatus").textContent = tc.automationKey || "No automation key set";
  document.getElementById("runStartBtn").disabled = !tc.automationKey;
  runOfflineBanner.hidden = true;
  runModal.classList.add("open");
}

function openRunAllModal() {
  const candidates = getFilteredTestCases().filter(tc => tc.automated && tc.automationKey);
  activeRunTc = null;
  activeRunKeys = candidates.map(tc => tc.automationKey);
  document.getElementById("runModalTitle").textContent = `Run All (${activeRunKeys.length} automated test${activeRunKeys.length === 1 ? "" : "s"} currently shown)`;
  document.getElementById("runOutput").textContent = "";
  document.getElementById("runStatus").textContent = activeRunKeys.length
    ? activeRunKeys.join(", ")
    : "No automated test cases with an automation key match the current filters.";
  document.getElementById("runStartBtn").disabled = activeRunKeys.length === 0;
  runOfflineBanner.hidden = true;
  runModal.classList.add("open");
}

document.getElementById("runAllBtn").addEventListener("click", openRunAllModal);

document.getElementById("runStartBtn").addEventListener("click", async () => {
  if (activeRunKeys.length === 0) return;
  const startBtn = document.getElementById("runStartBtn");
  const statusEl = document.getElementById("runStatus");
  const outputEl = document.getElementById("runOutput");
  const browser = document.getElementById("runBrowser").value;
  const headless = document.getElementById("runHeadless").checked;
  const isRunAll = !activeRunTc;

  startBtn.disabled = true;
  statusEl.textContent = `Running ${activeRunKeys.length} test(s) (${browser}, ${headless ? "headless" : "headed"})...`;
  outputEl.textContent = "";
  try {
    const result = isRunAll
      ? await apiPost("/api/run-all", { automationKeys: activeRunKeys, browser, headless })
      : await apiPost("/api/run-test", { automationKey: activeRunKeys[0], browser, headless });
    outputEl.textContent = result.output || "(no output captured)";
    await refreshExecutionResults();
    if (isRunAll) {
      const passCount = activeRunKeys.filter(k => (liveExecutionResults[k] || {}).status === "Pass").length;
      statusEl.textContent = `Result: ${passCount}/${activeRunKeys.length} passed (Maven exit code ${result.exitCode})`;
    } else {
      const state = getEffectiveState(activeRunTc);
      statusEl.textContent = `Result: ${state.status} (Maven exit code ${result.exitCode})`;
    }
    render();
  } catch (e) {
    statusEl.textContent = "";
    runOfflineBanner.hidden = false;
    outputEl.textContent = e.message;
  } finally {
    startBtn.disabled = false;
  }
});

document.getElementById("runCloseBtn").addEventListener("click", () => runModal.classList.remove("open"));

refreshFileDatalists();
refreshExecutionResults();
render();

